TEE_Result generate_key(unsigned long obj, unsigned long key_size, const struct utee_attribute* usr_params, unsigned long param_count) {
    TEE_Session* session = TEE_GetCurrentSession();
    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    if (key_size == 0) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    if (!usr_params && param_count > 0) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    if (param_count > TEE_MAX_ATTRIBUTES) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    struct utee_attribute* attributes = (struct utee_attribute*)TEE_Malloc(param_count * sizeof(struct utee_attribute), TEE_MALLOC_FILL_ZERO);
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    for (unsigned long i = 0; i < param_count; ++i) {
        if (TEE_MemMove(&attributes[i], &usr_params[i], sizeof(struct utee_attribute)) != TEE_SUCCESS) {
            TEE_Free(attributes);
            return TEE_ERROR_BAD_PARAMETERS;
        }
    }

    TEE_Result result = TEE_ERROR_GENERIC;

    if (obj == TEE_TYPE_AES) {
        result = TEE_GenerateAESKey(obj, key_size, attributes, param_count);
    } else if (obj == TEE_TYPE_RSA) {
        result = TEE_GenerateRSAKey(obj, key_size, attributes, param_count);
    } else if (obj == TEE_TYPE_DSA) {
        result = TEE_GenerateDSAKey(obj, key_size, attributes, param_count);
    } else {
        result = TEE_ERROR_NOT_SUPPORTED;
    }

    TEE_Free(attributes);
    return result;
}
